package com.bank.feed;

import java.util.*;
import java.util.logging.*;

public class FeedDemo {
    private static final Logger log = Logger.getLogger("Feed");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FollowGraph graph = new FollowGraph();
        PostStore posts = new PostStore();
        FeedCache cache = new FeedCache();
        FeedService feed = new FeedService(graph, posts, cache);

        // Rajesh follows advisor Priya (normal) and the announcements channel (celebrity)
        graph.follow("SAV2001", "ADVISOR-PRIYA");
        graph.follow("SAV2001", "NBI-ANNOUNCE");
        graph.markCelebrity("NBI-ANNOUNCE");

        // Priya posts (normal → fan-out-on-write to Rajesh)
        feed.publish("ADVISOR-PRIYA", new Post("p1", "ADVISOR-PRIYA",
            "Lock an FD now at 7.5%", 10, System.currentTimeMillis()));

        // Announcements channel posts (celebrity → NOT fanned out, pulled on read)
        posts.add(new Post("p2", "NBI-ANNOUNCE",
            "New UPI limit raised to 5 lakh", 50, System.currentTimeMillis() + 1000));

        // Rajesh opens his feed (hybrid build, ranked, first page)
        List<Post> page = feed.buildFeed("SAV2001", 10);
        log.info("Rajesh feed (ranked):");
        page.forEach(p -> log.info(() -> "  " + p.getId() + " score=" + feed.score(p) + " : " + p.getText()));
    }
}

