package com.bank.feed;

import java.util.*;

public class FollowGraph {
    private final Map<String, Set<String>> followees = new HashMap<>();
    private final Map<String, Set<String>> followers = new HashMap<>();
    private final Set<String> celebrities = new HashSet<>();

    public void follow(String user, String author) {
        followees.computeIfAbsent(user, k -> new HashSet<>()).add(author);
        followers.computeIfAbsent(author, k -> new HashSet<>()).add(user);
    }
    public Set<String> followersOf(String author) {
        return followers.getOrDefault(author, Set.of());
    }
    public Set<String> followeesOf(String user) {
        return followees.getOrDefault(user, Set.of());
    }
    public void markCelebrity(String author) { celebrities.add(author); }
    public boolean isCelebrity(String author) { return celebrities.contains(author); }
}
```

