package com.bank.feed;

import java.util.*;
import java.util.stream.*;

public class PostStore {
    private final Map<String, List<Post>> byAuthor = new HashMap<>();
    private final Map<String, Post> byId = new HashMap<>();
    public void add(Post p) {
        byAuthor.computeIfAbsent(p.getAuthorId(), k -> new ArrayList<>()).add(p);
        byId.put(p.getId(), p);
    }
    public Post byId(String id) { return byId.get(id); }
    public List<Post> recent(String author, int limit) {
        return byAuthor.getOrDefault(author, List.of()).stream()
            .sorted(Comparator.comparingLong(Post::getCreatedAt).reversed())
            .limit(limit).collect(Collectors.toList());
    }
}
