// ─── File: FeedCache.java ───
package com.bank.feed;

import java.util.*;

// Precomputed feed (list of post ids) per user — the fan-out-on-write store.
public class FeedCache {
    private final Map<String, Deque<String>> feeds = new HashMap<>();
    public void prepend(String userId, String postId) {
        feeds.computeIfAbsent(userId, k -> new ArrayDeque<>()).addFirst(postId);
    }
    public List<String> range(String userId, int from, int limit) {
        Deque<String> d = feeds.getOrDefault(userId, new ArrayDeque<>());
        return new ArrayList<>(d).subList(from, Math.min(from + limit, d.size()));
    }
}
```

```java
// ─── File: FeedService.java ───
package com.bank.feed;

import java.util.*;
import java.util.logging.*;

public class FeedService {
    private static final Logger log = Logger.getLogger("Feed");
    private final FollowGraph graph;
    private final PostStore posts;
    private final FeedCache cache;

    public FeedService(FollowGraph graph, PostStore posts, FeedCache cache) {
        this.graph = graph; this.posts = posts; this.cache = cache;
    }

    // publish: fan-out-on-write for normal authors; store only for celebrities
    public void publish(String authorId, Post post) {
        posts.add(post);
        if (graph.isCelebrity(authorId)) {
            log.info(() -> "celebrity post " + post.getId() + " NOT fanned out (pull on read)");
            return;
        }
        for (String follower : graph.followersOf(authorId)) {
            cache.prepend(follower, post.getId());  // push to each follower
            log.info(() -> "fan-out " + post.getId() + " -> feed of " + follower);
        }
    }

    // hybrid build: precomputed list + live pull from followed celebrities, then rank
    public List<Post> buildFeed(String userId, int limit) {
        List<Post> result = new ArrayList<>();
        for (String id : cache.range(userId, 0, limit)) {
            Post p = posts.byId(id);
            if (p != null) result.add(p);
        }
        for (String author : graph.followeesOf(userId)) {
            if (graph.isCelebrity(author)) result.addAll(posts.recent(author, limit));
        }
        result.sort(Comparator.comparingDouble(this::score).reversed()); // ranking
        return result.subList(0, Math.min(limit, result.size()));
    }

    // simple ranking score: engagement weighted, recency bonus
    public double score(Post p) {
        double recencyMinutes = (System.currentTimeMillis() - p.getCreatedAt()) / 60000.0;
        return p.getEngagement() * 1.0 - recencyMinutes * 0.1;
    }
}
```
